"""Bounded schema/hash/diversity assessment, explicitly not full body reading."""
import sys,json,hashlib,re,collections
sys.dont_write_bytecode=True
import additional_pfp_domain_remaining_audit as a
p='pfp/domain/immune/self_panel.json';raw=(a.ROOT/p).read_bytes();assert hashlib.sha256(raw).hexdigest()==a.row(p)['sha256'];d=json.loads(raw);es=d['entries'];sha=lambda b:hashlib.sha256(b).hexdigest()
bad=[{'entry_id':e['entry_id'],'stored':e['content_sha256'],'actual':sha(e['content'].encode())} for e in es if sha(e['content'].encode())!=e['content_sha256']]
bases=collections.Counter(re.sub(r'\s*-- index \d+ hash_mod_\d+\s*\Z','',e['content']) for e in es)
variants={
 'full_raw':sha(raw),
 'all_fields_except_seal_sorted_compact':sha(json.dumps({k:v for k,v in d.items() if k!='sealed_sha256'},sort_keys=True,separators=(',',':')).encode()),
 'entry_id_digest_count_from_strings_convention':sha(json.dumps({'entries':[{'entry_id':e['entry_id'],'content_sha256':e['content_sha256']} for e in es],'fixture_count':len(es)},sort_keys=True,separators=(',',':')).encode()),
 'entries_only_sorted_compact':sha(json.dumps(es,sort_keys=True,separators=(',',':')).encode())}
review={'path':p,'sha256':a.row(p)['sha256'],'full_source_read':False,'status':'bounded_schema_and_custody_assessment','assessment':'All1000 entry objects parsed and content hashes recomputed.40 unique base strings were emitted and substantively inspected, with25 generated suffix variants each; this is not a line-by-line review of6007 JSON lines. Clean/proof/physics categories are unverified labels: several Lean-like bodies omit necessary premises or referenced definitions (e.g. arbitrary d1*d0=0, arbitrary L symmetric, weak duality without feasibility). Source code is inert fixture text and was not compiled.25 content hashes disagree with current bytes. Supplied seal does not by itself certify custody or healthy ground truth.','checks':[
 {'rule':'schema_counts','status':'parsed','top_keys':sorted(d),'count':len(es),'declared_count':d['fixture_count'],'entry_ids_unique':len({e['entry_id'] for e in es})==len(es),'entry_shapes_valid':all(set(e)=={'entry_id','category','content','content_sha256'} and all(isinstance(v,str) for v in e.values()) for e in es),'categories':dict(collections.Counter(e['category'] for e in es))},
 {'rule':'content_sha256_binding','status':'mismatches_observed','checked':len(es),'mismatch_count':len(bad),'mismatches':bad},
 {'rule':'generated_content_diversity','status':'parsed_and_unique_base_texts_inspected','base_count':len(bases),'multiplicities':dict(collections.Counter(bases.values())),'bases':[{'content':k,'count':v} for k,v in sorted(bases.items())]},
 {'rule':'seal_candidate_conventions','status':'bounded_comparison_observed','stored_seal':d['sealed_sha256'],'candidate_hashes':variants,'matching_conventions':[k for k,v in variants.items() if v==d['sealed_sha256']],'limit':'No generation owner establishing the intended seal preimage was reviewed; these are enumerated candidate conventions, not exhaustive seal invalidity proof.'}
 ],'limits':['No full_source_read credit.','No Lean, physics solver or biological/self-tolerance ground truth validation.','No modification to canonical panel.']}
rows=a.read('_data_reviews.json') if a.file('_data_reviews.json').exists() else [];assert not any(x['path']==p for x in rows);rows.append(review);a.write('_data_reviews.json',rows)
n=a.read('_notes.json');n['findings'].append({'id':'PFPDOMAIN-F027','title':'Current self-panel content hashes disagree for25 fixtures','statement':'Recomputing UTF-8 SHA256 for all1000 stored fixture contents finds25 mismatches. The1000 entries reduce to40 distinct base strings after removing the declared synthetic index/hash suffix, each repeated25 times. The finite fixture corpus is not1000 independent verified proofs; its category labels and Lean-looking assertions do not establish correctness. The loader trust gap in F025 means these mismatches do not trigger refusal.','evidence':[p,'pfp/domain/immune/thymus.py'],'source_evidence':[{'path':p,'sha256':a.row(p)['sha256'],'assessment_mode':'bounded_json_parse_all_entries_and_unique_base_text_inspection','checks':'content_sha256_binding, generated_content_diversity'},{'path':'pfp/domain/immune/thymus.py','sha256':a.row('pfp/domain/immune/thymus.py')['sha256'],'lines':[[116,145]]}],'status':'confirmed_bounded_data_and_source','limits':'No full body reading of JSON, no claim about original generation or every possible seal preimage, no fixture execution.'});a.write('_notes.json',n);a.report();print(json.dumps({'bad_hashes':len(bad),'base_count':len(bases),'seal_matching_conventions':review['checks'][-1]['matching_conventions']},indent=2))
